import sqlalchemy
from sqlalchemy import Column, text
from sqlalchemy.sql import and_, or_

from ormar.queryset.actions.query_action import QueryAction

if TYPE_CHECKING:
    from ormar import Model
    from ormar.queryset.query import QuerySet


class FilterAction(QueryAction):
    def __init__(
        self, 
        filter_field: str, 
        value: Any, 
        owner: "Type[Model]", 
        queryset: "QuerySet"
    ) -> None:
        super().__init__(queryset=queryset, owner=owner)
        self.filter_field = filter_field
        self.value = value
        self.column_name, self.expression = self._get_column_name_and_expression()

    def _get_column_name_and_expression(self) -> Tuple[str, str]:
        parts = self.filter_field.split("__")
        if len(parts) > 1 and parts[-1] in self.filter_expressions:
            return "__".join(parts[:-1]), parts[-1]
        return self.filter_field, "exact"

    def get_text_clause(self) -> Optional[Any]:
        if self.column_name.startswith("__text_"):
            return text(self.value)
        return None

    def get_filter_clause(self, alias: "Type[Model]") -> Any:
        if self.column_name.startswith("__text_"):
            return self.get_text_clause()

        column = self.get_column_from_model(alias=alias)

        if self.expression == "exact":
            return column == self.value
        elif self.expression == "iexact":
            return sqlalchemy.func.lower(column) == self.value.lower()
        elif self.expression == "contains":
            return column.contains(self.value)
        elif self.expression == "icontains":
            return sqlalchemy.func.lower(column).contains(self.value.lower())
        elif self.expression == "startswith":
            return column.startswith(self.value)
        elif self.expression == "istartswith":
            return sqlalchemy.func.lower(column).startswith(self.value.lower())
        elif self.expression == "endswith":
            return column.endswith(self.value)
        elif self.expression == "iendswith":
            return sqlalchemy.func.lower(column).endswith(self.value.lower())
        elif self.expression == "isnull":
            if self.value:
                return column.is_(None)
            return column.isnot(None)
        elif self.expression == "gt":
            return column > self.value
        elif self.expression == "gte":
            return column >= self.value
        elif self.expression == "lt":
            return column < self.value
        elif self.expression == "lte":
            return column <= self.value
        elif self.expression == "in":
            return column.in_(self.value)
        elif self.expression == "between":
            return and_(column >= self.value[0], column <= self.value[1])
        elif self.expression == "not_in":
            return sqlalchemy.not_(column.in_(self.value))
        elif self.expression == "not_between":
            return or_(column < self.value[0], column > self.value[1])
        else:
            raise ValueError(f"Unsupported expression: {self.expression}")
